// FLDesignTokens tests — Direction H and P documented contrast claims.
//
// Same contract as ContrastTests (Direction F): the WCAG 2.1 machinery is
// implemented here in the test target and computes straight from the public
// token channels; every assertion checks the computed ratio against the
// direction's documented claim, within 0.1. A larger disagreement FAILS and
// prints computed vs claimed — the doc or the token then gets corrected and
// the row below is updated.
//
// Sources of the claims:
// - H: the direction-h round's `contrast-table.md` (generated by that
//   round's `tools/contrast.mjs`): 42 rows — 13 per mode plus the
//   light/dark accent-button-label rows and the cook photo-placeholder row.
//   NOTE: DIRECTION.md's tally sentence says "53 text pairs and 8 non-text
//   pairs"; the table that tool actually generates and prints is these 42
//   rows. The suite asserts every row the tool defines; the tally sentence
//   in the H doc is flagged for the PR body's correction list.
// - P: DIRECTION.md §5's tables: 56 text rows (26 light + 21 dark + 9 cook)
//   and 8 non-text rows.

import XCTest
@testable import FLDesignTokens

final class DirectionContrastTests: XCTestCase {

    // MARK: WCAG 2.1 machinery (test-target implementation)

    private func linear(_ channel: Double) -> Double {
        if channel <= 0.03928 {
            return channel / 12.92
        }
        return pow((channel + 0.055) / 1.055, 2.4)
    }

    private func luminance(_ color: ColorToken) -> Double {
        0.2126 * linear(color.red)
            + 0.7152 * linear(color.green)
            + 0.0722 * linear(color.blue)
    }

    private func contrast(_ foreground: ColorToken, _ background: ColorToken) -> Double {
        let lf = luminance(foreground)
        let lb = luminance(background)
        return (max(lf, lb) + 0.05) / (min(lf, lb) + 0.05)
    }

    // MARK: Claim rows

    /// H's token roles, resolved per palette. Enums are Sendable, so the
    /// claim tables below stay concurrency-safe under Swift 6.
    private enum HRole: String, Sendable {
        case bg, surface, ink, ink2, ink3, rule, rule2
        case accent, accentSoft, accentInk, error
        case buttonFill, buttonLabel, photoPlaceholder, pillIdle, pillGone

        func token(in p: HPalette) -> ColorToken {
            switch self {
            case .bg: return p.bg
            case .surface: return p.surface
            case .ink: return p.ink
            case .ink2: return p.ink2
            case .ink3: return p.ink3
            case .rule: return p.rule
            case .rule2: return p.rule2
            case .accent: return p.accent
            case .accentSoft: return p.accentSoft
            case .accentInk: return p.accentInk
            case .error: return p.error
            case .buttonFill: return p.buttonFill
            case .buttonLabel: return p.buttonLabel
            case .photoPlaceholder: return p.photoPlaceholder
            case .pillIdle: return p.pillIdle
            case .pillGone: return p.pillGone
            }
        }
    }

    private struct HClaim: Sendable {
        let mode: DirectionMode
        let foreground: HRole
        let background: HRole
        let use: String
        /// The ratio as printed in the round's contrast-table.md.
        let claimed: Double
    }

