        func token(in p: PPalette) -> ColorToken {
            switch self {
            case .bg: return p.bg
            case .surface: return p.surface
            case .surfaceMuted: return p.surfaceMuted
            case .surfaceDeep: return p.surfaceDeep
            case .ink: return p.ink
            case .ink2: return p.ink2
            case .ink3: return p.ink3
            case .rule: return p.rule
            case .rule2: return p.rule2
            case .accent: return p.accent
            case .accentInk: return p.accentInk
            case .accentSoft: return p.accentSoft
            case .sage: return p.sage
            case .sageInk: return p.sageInk
            case .sageChip: return p.sageChip
            case .sagePlate: return p.sagePlate
            case .oat: return p.oat
            case .oatChip: return p.oatChip
            case .oatInk: return p.oatInk
            case .dustyRose: return p.dustyRose
            case .roseChip: return p.roseChip
            case .accentLight: return p.accentLight
            case .deepOlive: return p.deepOlive
            case .buttonFill: return p.buttonFill
            case .buttonLabel: return p.buttonLabel
            case .error: return p.error
            }
        }
    }

