    // MARK: Tests

    /// Every H claim computes within 0.1 of the documented ratio.
    func testDirectionHDocumentedContrastClaimsWithinTenth() {
        for claim in Self.hClaims {
            let palette = DirectionH.palette(claim.mode)
            let computed = contrast(
                claim.foreground.token(in: palette),
                claim.background.token(in: palette)
            )
            XCTAssert(
                abs(computed - claim.claimed) <= 0.1,
                "H \(claim.mode.rawValue) '\(claim.use)': computed \(String(format: "%.2f", computed)), claimed \(claim.claimed)"
            )
        }
    }

    /// Every P claim computes within 0.1 of the documented ratio.
    func testDirectionPDocumentedContrastClaimsWithinTenth() {
        for claim in Self.pClaims {
            let palette = DirectionP.palette(claim.mode)
            let computed = contrast(
                claim.foreground.token(in: palette),
                claim.background.token(in: palette)
            )
            XCTAssert(
                abs(computed - claim.claimed) <= 0.1,
                "P \(claim.mode.rawValue) '\(claim.use)': computed \(String(format: "%.2f", computed)), claimed \(claim.claimed)"
            )
        }
    }

    /// The harness tables cover exactly what the docs document:
    /// H 42 rows, P 56 text + 8 non-text. A doc edit that adds a pair must
    /// add the claim row too — the count guards silent drift.
    func testDirectionClaimTablesMatchTheDocumentedRowCounts() {
        XCTAssertEqual(Self.hClaims.count, 42, "H contrast-table.md defines 42 rows")
        XCTAssertEqual(Self.pClaims.count, 64, "P §5 defines 56 text + 8 non-text rows")
    }
